"use client";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import * as Primitive from "@radix-ui/react-toast";
import { useFlowAppearance } from "@/lib/sahajiv-motion/use-flow";
export const toastVariants = cva(
  "v-toast [display:flex] [align-items:center] [gap:var(--s-3)] [padding:var(--s-3)_var(--s-4)] [border-radius:var(--r-card-sm)] [background:var(--v-ink)] [color:var(--v-on-ink)] [font-size:var(--fs-control)]",
  {
    variants: { variant: { default: "", cream: "-cream", danger: "-danger" } },
    defaultVariants: { variant: "default" },
  },
);
export type ToastProviderProps = React.ComponentProps<
  typeof Primitive.Provider
>;
export function ToastProvider(props: ToastProviderProps) {
  return <Primitive.Provider duration={5000} {...props} />;
}
export type ToastViewportProps = React.ComponentProps<
  typeof Primitive.Viewport
>;
export function ToastViewport({ className, ...props }: ToastViewportProps) {
  return (
    <Primitive.Viewport
      data-slot="toast-viewport"
      data-part="viewport"
      className={cn(
        "v-toaster fixed right-[var(--s-6)] bottom-[var(--s-6)] grid gap-[var(--s-2)] z-[var(--z-toast)] w-[min(380px,calc(100%-48px))]",
        className,
      )}
      {...props}
    />
  );
}
export type ToastProps = React.ComponentProps<typeof Primitive.Root> &
  VariantProps<typeof toastVariants> & { durable?: boolean };
export function Toast({
  className,
  variant,
  durable,
  duration,
  ref,
  ...props
}: ToastProps) {
  const morphRef = useMorph<HTMLLIElement>("surfaces", ref);
  const flowRef = useFlowAppearance<HTMLLIElement>(
    props.open ?? true,
    morphRef,
    "enter",
  );
  return (
    <Primitive.Root
      ref={flowRef}
      data-slot="toast"
      data-part="root"
      duration={durable ? Infinity : duration}
      className={cn(toastVariants({ variant }), className)}
      {...props}
    />
  );
}
export type ToastTitleProps = React.ComponentProps<typeof Primitive.Title>;
export function ToastTitle({ className, ...props }: ToastTitleProps) {
  return (
    <Primitive.Title
      data-slot="toast-title"
      data-part="title"
      className={cn("font-medium", className)}
      {...props}
    />
  );
}
export type ToastDescriptionProps = React.ComponentProps<
  typeof Primitive.Description
>;
export function ToastDescription({
  className,
  ...props
}: ToastDescriptionProps) {
  return (
    <Primitive.Description
      data-slot="toast-description"
      data-part="description"
      className={cn("flex-1", className)}
      {...props}
    />
  );
}
export type ToastActionProps = React.ComponentProps<typeof Primitive.Action>;
export function ToastAction({
  className,
  asChild,
  children,
  ...props
}: ToastActionProps) {
  return (
    <Primitive.Action
      data-slot="toast-action"
      data-part="action"
      className={className}
      asChild
      {...props}
    >
      {asChild ? children : <Button>{children}</Button>}
    </Primitive.Action>
  );
}

export type ToastCloseProps = React.ComponentProps<typeof Primitive.Close>;
export function ToastClose({
  className,
  children,
  asChild,
  ...props
}: ToastCloseProps) {
  return (
    <Primitive.Close
      data-slot="toast-close"
      data-part="close"
      aria-label="Dismiss"
      className={className}
      asChild
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <Button style={{ minWidth: 30, padding: 0 }}>{children ?? "×"}</Button>
      )}
    </Primitive.Close>
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-danger {
  color: var(--destructive-foreground);
}
.v-toaster:where([data-slot="toast"], [data-slot^="toast-"]) {
  position: fixed;
  right: var(--s-6);
  bottom: var(--s-6);
  display: grid;
  gap: var(--s-2);
  z-index: var(--z-toast);
  width: min(380px, calc(100% - 48px));
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]) {
  animation: v-toast-in var(--t-max) var(--enter);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-cream {
  background: var(--v-canvas);
  color: var(--v-text);
  border: 1px solid var(--v-border);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-danger {
  background: var(--v-danger-fill);
  color: var(--destructive-foreground);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]) .v-btn {
  height: 30px;
  padding: 0 12px;
  font-size: 12px;
  margin-left: auto;
  background: rgba(251, 244, 230, 0.14);
  color: inherit;
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-cream .v-btn {
  background: var(--v-beige);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-out {
  animation: v-toast-out var(--t-element) var(--exit) forwards;
}
@keyframes v-toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
@keyframes v-toast-out {
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="toast"],
  [data-slot^="toast-"],
  [data-slot="toast"]::before,
  [data-slot="toast"]::after,
  [data-slot^="toast-"]::before,
  [data-slot^="toast-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="toast"][data-state="closed"] {
  animation: v-toast-out var(--t-element) var(--exit) forwards;
}
[data-slot="toast"][data-swipe="move"] {
  transform: translateX(var(--radix-toast-swipe-move-x));
}
[data-slot="toast"][data-swipe="end"] {
  transform: translateX(var(--radix-toast-swipe-end-x));
  opacity: 0;
}
[data-slot="toast"] { min-width:0; flex-wrap:wrap; overflow-wrap:anywhere; }
[data-slot="toast-title"], [data-slot="toast-description"] { min-width:0; }
[data-slot="toast-action"], [data-slot="toast-close"] { flex-shrink:0; }

}
